create temporary table opportunity_eligibility_targets on commit drop as
select o.id, r.title, r.evidence, r.patch, r.review
from opportunity_eligibility_review r
join public.opportunities o on o.title=r.title and (r.url='' or r.url=o.source_url)
where not o.is_sample and o.verification_status='verified';

update public.opportunities o
set min_grade = case when r.patch ? 'min_grade' then (r.patch->>'min_grade')::smallint else o.min_grade end,
    max_grade = case when r.patch ? 'max_grade' then (r.patch->>'max_grade')::smallint else o.max_grade end,
    min_age = case when r.patch ? 'min_age' then (r.patch->>'min_age')::smallint else o.min_age end,
    max_age = case when r.patch ? 'max_age' then (r.patch->>'max_age')::smallint else o.max_age end,
    age_reference_date = case when r.patch ? 'age_reference_date' then (r.patch->>'age_reference_date')::date else o.age_reference_date end,
    is_paid = case when r.patch ? 'is_paid' then (r.patch->>'is_paid')::boolean else o.is_paid end,
    work_mode = case when r.patch ? 'work_mode' then (r.patch->>'work_mode')::text else o.work_mode end,
    schedule_period = case when r.patch ? 'schedule_period' then (r.patch->>'schedule_period')::text else o.schedule_period end,
    application_open_date = case when r.patch ? 'application_open_date' then (r.patch->>'application_open_date')::date else o.application_open_date end,
    application_deadline = case when r.patch ? 'application_deadline' then (r.patch->>'application_deadline')::date else o.application_deadline end,
    citizenship_requirement = case when r.patch ? 'citizenship_requirement' then (r.patch->>'citizenship_requirement')::text else o.citizenship_requirement end,
    compensation_description = case when r.patch ? 'compensation_description' then (r.patch->>'compensation_description')::text else o.compensation_description end,
    min_gpa = case when r.patch ? 'min_gpa' then (r.patch->>'min_gpa')::numeric else o.min_gpa end,
    allowed_states = case when r.patch ? 'allowed_states' then array(select jsonb_array_elements_text(r.patch->'allowed_states')) else o.allowed_states end,
    allowed_counties = case when r.patch ? 'allowed_counties' then array(select jsonb_array_elements_text(r.patch->'allowed_counties')) else o.allowed_counties end,
    unstructured_requirements = case when r.patch ? 'req' then array(select jsonb_array_elements_text(r.patch->'req')) else o.unstructured_requirements end,
    archived_at = case when r.patch @> '{"archive":true}' then coalesce(o.archived_at, now()) else o.archived_at end
from opportunity_eligibility_targets r
where o.id=r.id and r.patch <> '{}'::jsonb;

insert into public.opportunity_admin as a (opportunity_id,source_evidence)
select id,jsonb_build_object('eligibility_review',jsonb_build_object('date','2026-11-25','source',nullif(evidence,''),'status',review))
from opportunity_eligibility_targets
on conflict (opportunity_id) do update
set source_evidence = a.source_evidence || excluded.source_evidence;

select
  (select count(*) from opportunity_eligibility_review) as reviewed,
  (select count(*) from opportunity_eligibility_targets) as matched_database_rows,
  (select count(*) from opportunity_eligibility_targets where patch <> '{}'::jsonb) as updated,
  (select count(*) from public.public_opportunities) as public_listings,
  (select count(*) from public.opportunities o join opportunity_eligibility_targets t on o.id=t.id
    where o.archived_at is null and num_nonnulls(o.min_age,o.max_age,o.min_grade,o.max_grade)=0
    and cardinality(o.eligible_graduation_years)=0) as no_age_or_grade,
  (select string_agg(r.title, ' | ') from opportunity_eligibility_review r where not exists
    (select 1 from opportunity_eligibility_targets t where t.title=r.title)) as unmatched_titles;
commit;
